<template><div class="login-modal-overlay" @click.self="$emit('close')"><div class="login-modal"><div class="login-modal-header"><span class="login-modal-title">{{isForgot?t('forgotPassword'):(isRegister?t('registerTitle'):t('loginTitle'))}}</span><button class="login-modal-close" @click="$emit('close')">✕</button></div><form @submit.prevent="submit"><div class="login-modal-body"><input v-if="!isForgot" v-model="username" class="login-modal-input" :placeholder="t('usernamePlaceholder')" required><input v-if="isRegister||isForgot" v-model="email" class="login-modal-input" type="email" :placeholder="isRegister?t('registerEmailPlaceholder'):t('emailPlaceholder')" :required="isForgot"><template v-if="isForgot&&codeSent"><input v-model="resetCode" class="login-modal-input" :placeholder="t('emailCodePlaceholder')" maxlength="6" required><input v-model="resetPassword" class="login-modal-input" type="password" :placeholder="t('newPasswordPlaceholder')" required><input v-model="resetConfirm" class="login-modal-input" type="password" :placeholder="t('confirmPasswordPlaceholder')" required></template><input v-if="!isForgot" v-model="password" class="login-modal-input" type="password" :placeholder="t('passwordPlaceholder')" required><template v-if="isRegister"><input v-model="nickname" class="login-modal-input" :placeholder="t('nicknamePlaceholder')"><div class="avatar-selection"><p>{{t('chooseAvatar')}}</p><div class="avatar-options"> <div v-for="a in avatars" :key="a" :class="['avatar-option',{selected:avatar===a}]" @click="avatar=a"><AvatarIcon :type="a" :size="40"/></div></div></div></template><div v-if="error" class="login-modal-error">{{error}}</div><a v-if="appeal" class="login-modal-appeal-link" href="https://t.me/CyrusOliver" target="_blank">账号申诉</a><div v-if="message" class="login-modal-success">{{message}}</div><button class="login-modal-submit" type="submit" :disabled="loading">{{loading?t('processing'):(isForgot?(codeSent?t('confirmReset'):t('sendResetCode')):(isRegister?t('register'):t('loginBtn')))}}</button></div></form><div class="login-modal-footer"><button class="login-modal-action" @click="switchMode(isRegister||isForgot?'login':'register')">{{isRegister||isForgot?t('backToLogin'):t('registerAccount')}}</button><button v-if="!isRegister&&!isForgot" class="login-modal-action" @click="switchMode('forgot')">{{t('forgotPassword')}}</button></div></div></div></template>
<script setup>import {computed,ref} from 'vue';import {useAuth,useLang} from '../contexts/app';import {authService} from '../services/authService';import AvatarIcon from './AvatarIcon.vue';import './LoginModal.css';defineEmits(['close']);const {login}=useAuth();const {t}=useLang();const mode=ref('login'),username=ref(''),password=ref(''),nickname=ref(''),email=ref(''),resetCode=ref(''),resetPassword=ref(''),resetConfirm=ref(''),codeSent=ref(false),avatar=ref('eye'),error=ref(''),message=ref(''),appeal=ref(false),loading=ref(false);const avatars=['eye','ear','nose','mouth'];const isRegister=computed(()=>mode.value==='register'),isForgot=computed(()=>mode.value==='forgot');const switchMode=(m)=>{mode.value=m;error.value=message.value='';appeal.value=false;codeSent.value=false};const submit=async()=>{error.value=message.value='';appeal.value=false;loading.value=true;try{if(isForgot.value){if(!codeSent.value){const d=await authService.forgotPassword(email.value);codeSent.value=true;message.value=d.detail||t('resetCodeSent')}else{if(resetPassword.value.length<4)throw {message:t('passwordMinLength')};if(resetPassword.value!==resetConfirm.value)throw {message:t('passwordMismatch')};const d=await authService.resetPassword(email.value,resetCode.value,resetPassword.value);message.value=d.detail||t('passwordResetSuccess')}}else{const d=isRegister.value?await authService.register(username.value,password.value,nickname.value||username.value,avatar.value,email.value):await authService.login(username.value,password.value);login(d.user,d.token);emit('close')}}catch(e){appeal.value=!isForgot.value&&!isRegister.value&&e.response?.status===403;error.value=e.response?.data?.detail||e.message||t('loginFailed')}finally{loading.value=false}};</script>
<style scoped>.avatar-options{display:flex;gap:10px;justify-content:center}.avatar-option{padding:3px;border:2px solid transparent;border-radius:8px}.avatar-option.selected{border-color:red}</style>
